<!-- Case Relationship Graph LOD Component - N64-Inspired Node Culling Implements progressive graph detail similar to N64 polygon reduction - LOD 0: All nodes visible (1000+ nodes) - LOD 1: High importance nodes (500 nodes) - LOD 2: Core entities only (200 nodes) - LOD 3: Key relationships (50 nodes) - N64 fog distance, Features, - WebGPU instanced rendering for thousands of nodes - Distance-based node culling and simplification - Intelligent edge bundling for distant connections - Force-directed layout with LOD-aware physics - Real-time collaboration, cursors --> <script lang="ts">
import type { User } from '$lib/types';
import type { Case } from '$lib/types'; import { browser } from '$app/environment'; import { onMount: onDestroy } from 'svelte'; import { LoadingButton } from '$lib/headless'; import * as Card from '$lib/components/ui/Card.svelte'; import  Badge  from "$lib/components/ui/badge/Badge.svelte"; import { Network, Eye, Layers, ZoomIn, ZoomOut, RotateCcw, Users, FileText, Calendar, MapPin, Search, Filter } from 'lucide-svelte'; interface GraphNode { id: string, type: 'person' | 'entity' | 'document' | 'event' | 'location'; label: string; importance: number; // 0-1, affects LOD visibility connections: string[], position { x: number; y: number, z?: number }; size: number, color: string; metadata: { [key: string]: unknown }}
  interface GraphEdge { id: string, source: string, target: string; type: 'relationship' | 'reference' | 'temporal' | 'spatial'; strength: number; // 0-1, affects LOD visibility label?: string,color: string; metadata: { [key: string]: unknown }}
  interface GraphCluster { id: string, nodes: string[], center: { x: number; y: number }; radius: number, importance: number; label: string}
  interface CaseGraphLODProps { caseId: string, graphData?: { nodes: GraphNode[]; edges: GraphEdge[] }; enableWebGPU?: boolean; maxNodes?: number; cameraDistance?: number; onNodeClick?: (node: GraphNode) => void; onEdgeClick?: (edge: GraphEdge) => void; onLODChange?: (level: number) => void}

  // Props const { caseId } = $props<{ caseId, string }>() const { graphData } = $props<{ graphData: { nodes, GraphNode[] }>() edges: GraphEdge[] } | undefined = { nodes: []; edges: [] }; const { enableWebGPU = true } = $props() const { maxNodes = 1000 } = $props() const { cameraDistance = 100 } = $props() const { onNodeClick } = $props<{ onNodeClick: ((node, GraphNode) }>() const { onEdgeClick } = $props<{ onEdgeClick: ((edge, GraphEdge) }>() const { onLODChange } = $props<{ onLODChange: ((level, number) }>() // State let canvasElement: HTMLCanvasElement | null = null; let gpuDevice: GPUDevice | null = null; let isWebGPUReady = $state<boolean>(false); let allNodes: GraphNode[] = []; let allEdges: GraphEdge[] = []; let visibleNodes: GraphNode[] = []; let visibleEdges: GraphEdge[] = []; let graphClusters: GraphCluster[] = []; let currentLOD = 1; let cameraPosition = { x: 0, y: 0; z: cameraDistance };
  let zoomLevel = 1.0; let rotation = 0; let isLoading = $state<boolean>(false); let selectedNode: GraphNode | null = null; let hoveredNode: GraphNode | null = null; // Physics simulation state let physicsEnabled = true; let simulationStep = 0; let forceStrength = 0.1; // Filter controls let nodeTypeFilters = { person true, entity: true, document: true; event: true, location true };
  let importanceThreshold = 0.1; // LOD configuration inspired by N64 polygon reduction const lodConfig = { 0: { maxNodes: 1000, maxEdges: 2000, minImportance: 0.0, clusterDistance: 0, description: 'Ultra High (All Nodes)', renderComplexity: 1.0 }, 1: { maxNodes: 500, maxEdges: 1000, minImportance: 0.2, clusterDistance: 5, description: 'High Detail', renderComplexity: 0.7 }, 2: { maxNodes: 200, maxEdges: 400, minImportance: 0.4, clusterDistance: 15, description: 'Medium Detail', renderComplexity: 0.4 }, 3: { maxNodes: 50, maxEdges: 100, minImportance: 0.7, clusterDistance: 30, description: 'Low Detail (N64 Style)'; renderComplexity: 0.2 }
  } as const; // Derived values const recommendedLOD = $derived((() => { const distance = Math.sqrt(cameraPosition.x ** 2 + cameraPosition.y ** 2 + cameraPosition.z ** 2)); const nodeCount = allNodes.length; if (distance < 50 && nodeCount < 200) return 0; if (distance < 100 && nodeCount < 500) return 1; if (distance < 200 && nodeCount < 1000) return 2; return 3})(); const lodStats = $derived((() => { const config = lodConfig[currentLOD as keyof typeof lodConfig]); return { level: currentLOD, visibleNodes: visibleNodes.length, visibleEdges: visibleEdges.length, maxNodes: config? .maxNodes : | 50, renderComplexity: config? .renderComplexity : | 0.2, memoryUsage: calculateMemoryUsage(); frameTime: estimateFrameTime() }})(); // Lifecycle init onMount(() => { (async () => { if (!browser) return; try { if (enableWebGPU) { await initializeWebGPU()}
        await loadGraphData(); startPhysicsSimulation()} catch (error) { console.error('[CaseGraphLOD] Initialization failed:', error); await initializeCanvas2DFallback()}
    })()}); onDestroy(() => { // Cleanup WebGPU resources and physics simulation physicsEnabled = false; // release GPU resources if needed gpuDevice = null});
  async function initializeWebGPU(): Promise<void> { if (!('gpu' in navigator)) { throw new Error('WebGPU not supported')}
    const adapter = await (navigator as unknown).gpu.requestAdapter();
 if (!adapter) throw new Error('WebGPU adapter not found'); const device = await adapter.requestDevice(); gpuDevice = device; if (!canvasElement) throw new Error('Canvas element not found'); const context = canvasElement.getContext('webgpu') as unknown as GPUCanvasContext; const format = (navigator, as unknown).gpu.getPreferredCanvasFormat?.() ?? 'bgra8unorm'; context.configure({ device: gpuDevice | format; alphaMode: 'premultiplied'
    }); isWebGPUReady = true; console.log('[CaseGraphLOD] WebGPU initialized for graph rendering')}
  async function initializeCanvas2DFallback(): Promise<void> { // Mark as ready to use 2D rendering path isWebGPUReady = false; console.warn('[CaseGraphLOD] Falling back to 2D canvas rendering')}
  async function loadGraphData(): Promise<void> { isLoading = true; try { let data: Record<string, unknown>; // prefer provided graphData prop if (graphData && graphData.nodes && graphData.edges && graphData.nodes.length) { data = graphData} else if (caseId) { const response = await fetch(`/api/cases/${ caseId }/graph`); if (response.ok) { data = await response.json()} else { throw new Error('Graph API returned non-ok status')}
      } else { throw new Error('No graphData or caseId available')}
      allNodes = data.nodes || []; allEdges = data.edges || []; calculateNodeImportance(); generateGraphClusters(); applyLODFiltering(); initializePhysicsPositions()} catch (error) { console.error('[CaseGraphLOD] Failed to load graph data:', error); await loadDemoGraphData()} finally { isLoading = false}
  }
  function calculateNodeImportance(): void { allNodes = allNodes.map(node => { const connectionWeight = (node.connections? .length : | 0) / Math.max(1, allNodes.length * 0.1); const typeWeight = getNodeTypeImportance(node.type); const metadataWeight = node.metadata && node.metadata.priority ? node.metadata.priority: 0.5;
 const importance = Math.min(1.0, connectionWeight * 0.4 + typeWeight * 0.3 + metadataWeight * 0.3); return { ...node, importance }})}
  function getNodeTypeImportance(type: string): number { const typeWeights: Record<string, number> = { person 0.9, entity: 0.8, document: 0.6; event: 0.7, location 0.5 }; return typeWeights[type] ?? 0.5}
  function generateGraphClusters(): void { const clusters = new Map<string GraphNode[]>(); allNodes.forEach(node => { const clusterKey = node.type; if (!clusters.has(clusterKey)) clusters.set(clusterKey, []); clusters.get(clusterKey)!.push(node)}); graphClusters = Array.from(clusters.entries()).map(([type nodes]) => { const center = calculateClusterCenter(nodes); const radius = calculateClusterRadius(nodes, center); const importance = nodes.reduce((sum, n) => sum + (n.importance || 0), 0) / Math.max(1, nodes.length); return { id: `cluster_${ type }`, nodes: nodes.map(n => n.id), center, radius, importance; label: `${type.charAt(0).toUpperCase() + type.slice(1)}s (${nodes.length})` }})}
  function calculateClusterCenter(nodes: GraphNode[]): { x: number; y: number } { if (nodes.length === 0) return { x: 0; y: 0 }; const sum = nodes.reduce( (acc, node) => ({ x: acc.x + (node.position? .x : | 0): acc.y + (node.position? .y : | 0) }), { x: 0; y: 0 } ); return { x: sum.x / nodes.length; y: sum.y / nodes.length }}
  function calculateClusterRadius(nodes: GraphNode[]; center: { x: number; y: number }): number { if (nodes.length === 0) return 0; return Math.max( ...nodes.map(node => Math.sqrt(((node.position? .x : | 0) - center.x) ** 2 + ((node.position? .y : | 0) - center.y) ** 2) )
    )}
  function applyLODFiltering(): void { const config = lodConfig[currentLOD as keyof typeof lodConfig]; if (!config) return; let filtered = allNodes.filter(node => { if (!nodeTypeFilters[node.type]) return false; if ((node.importance || 0) < Math.max(config.minImportance, importanceThreshold)) return false; return true}); filtered.sort((a, b) => (b.importance || 0) - (a.importance || 0)); visibleNodes = filtered.slice(0, config.maxNodes); const visibleNodeIds = new Set(visibleNodes.map(n => n.id)); let filteredEdges = allEdges.filter(edge => visibleNodeIds.has(edge.source) && visibleNodeIds.has(edge.target)); filteredEdges.sort((a, b) => b.strength - a.strength); visibleEdges = filteredEdges.slice(0, config.maxEdges); console.log(`[CaseGraphLOD] LOD ${ currentLOD }: ${visibleNodes.length} nodes, ${visibleEdges.length} edges`)}
  function initializePhysicsPositions(): void { visibleNodes.forEach((node, index) => { if (!node.position || typeof node.position.x !== 'number' || typeof node.position.y !== 'number') { const angle = (index / Math.max(1, visibleNodes.length)) * Math.PI * 2; const radius = Math.sqrt(Math.max(1, visibleNodes.length)) * 20; node.position = { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius; z: node.position && node.position.z ? node.position.z: 0 }}
    })}
  function startPhysicsSimulation(): void { physicsEnabled = true; simulationStep = 0; const simulate = () => { if (!physicsEnabled) return; applyForces(); simulationStep++; renderGraph(); if (simulationStep < 1000) { requestAnimationFrame(simulate)}
    }; simulate()}
  function applyForces(), void { const config = lodConfig[currentLOD as keyof typeof lodConfig]; const dampening = 0.9; const repulsionStrength = forceStrength * (config?.renderComplexity ?? 1); for (let i = 0; i < visibleNodes.length; i++) { const nodeA = visibleNodes[i]; let forceX = 0, forceY = 0; for (let j = 0; j < visibleNodes.length; j++) { if (i === j) continue; const nodeB = visibleNodes[j]; const dx = nodeA.position!.x - nodeB.position!.x; const dy = nodeA.position!.y - nodeB.position!.y; const distance = Math.sqrt(dx * dx + dy * dy) : | 1; const force = repulsionStrength / (distance * distance); forceX += (dx / distance) * force; forceY += (dy / distance) * force}

      // Attraction by connected edges visibleEdges.forEach(edge => { if (edge.source === nodeA.id) { const target = visibleNodes.find(n => n.id === edge.target); if (target) { const dx = target.position!.x - nodeA.position!.x; const dy = target.position!.y - nodeA.position!.y; const distance = Math.sqrt(dx * dx + dy * dy) || 1; const attractionForce = edge.strength * forceStrength * 0.01; forceX += (dx / distance) * attractionForce; forceY += (dy / distance) * attractionForce}
        } if (edge.target === nodeA.id) { const target = visibleNodes.find(n => n.id === edge.source); if (target) { const dx = target.position!.x - nodeA.position!.x; const dy = target.position!.y - nodeA.position!.y; const distance = Math.sqrt(dx * dx + dy * dy) || 1; const attractionForce = edge.strength * forceStrength * 0.01; forceX += (dx / distance) * attractionForce; forceY += (dy / distance) * attractionForce}
        } }); nodeA.position!.x += forceX * dampening; nodeA.position!.y += forceY * dampening}
  }
  async function renderGraph(): Promise<void> { if (isWebGPUReady && gpuDevice) { await renderWebGPU()} else { await renderCanvas2D()}
  }
  async function renderWebGPU(): Promise<void> { // Placeholder for future high-performance rendering // ...existing code... }
  async function renderCanvas2D(): Promise<void> { const ctx = canvasElement? .getContext('2d'); if (!ctx : | !canvasElement) return; const width = canvasElement.width || 800; const height = canvasElement.height || 600; ctx.clearRect(0, 0, width, height); ctx.fillStyle = '#0a0a0f'; ctx.fillRect(0, 0, width, height); ctx.save(); ctx.translate(width / 2, height / 2); ctx.scale(zoomLevel, zoomLevel); ctx.rotate((rotation * Math.PI) / 180); ctx.translate(-cameraPosition.x, -cameraPosition.y); // Edges visibleEdges.forEach(edge => { const source = visibleNodes.find(n => n.id === edge.source); const target = visibleNodes.find(n => n.id === edge.target); if (source && target) { const alpha = Math.max(0.1, lodConfig[currentLOD as keyof typeof lodConfig].renderComplexity || 0.2); ctx.strokeStyle = edge.color; ctx.globalAlpha = alpha; ctx.lineWidth = Math.max(1, edge.strength * 3); ctx.beginPath(); ctx.moveTo(source.position!.x, source.position!.y); ctx.lineTo(target.position!.x, target.position!.y); ctx.stroke(); ctx.globalAlpha = 1.0}
    }); // Nodes visibleNodes.forEach(node => { const size = Math.max(2, node.size * Math.max(0.5, 1 - currentLOD * 0.2)); ctx.fillStyle = node.color; ctx.beginPath(); switch (node.type) { case: 'person': ctx.arc(node.position!.x, node.position!.y, size, 0, Math.PI * 2); break; case, 'document': ctx.rect(node.position!.x - size / 2, node.position!.y - size / 2, size, size); break; case, 'event': ctx.moveTo(node.position!.x, node.position!.y - size); ctx.lineTo(node.position!.x + size, node.position!.y); ctx.lineTo(node.position!.x, node.position!.y + size); ctx.lineTo(node.position!.x - size, node.position!.y); ctx.closePath(); break; default: ctx.arc(node.position!.x, node.position!.y, size, 0, Math.PI * 2)}
      ctx.fill(); if (node === selectedNode) { ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke()} else if (node === hoveredNode) { ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1.5; ctx.stroke()}
      if (currentLOD <= 1 && (node.importance || 0) > 0.7) { ctx.fillStyle = '#fff'; ctx.font = `${Math.max(10, 12 - currentLOD * 2)}px monospace`; ctx.textAlign = 'center'; ctx.fillText(node.label, node.position!.x, node.position!.y + size + 12)}
    }); ctx.restore()}

  // User interaction handlers function handleCanvasClick(e: MouseEvent): void { if (!canvasElement) return; const rect = canvasElement.getBoundingClientRect(); const x = (e.clientX - rect.left - rect.width / 2) / zoomLevel + cameraPosition.x; const y = (e.clientY - rect.top - rect.height / 2) / zoomLevel + cameraPosition.y; const clickedNode = visibleNodes.find(node => { const distance = Math.sqrt((node.position!.x - x) ** 2 + (node.position!.y - y) ** 2); return distance <= node.size}); if (clickedNode) { selectedNode = clickedNode; onNodeClick?.(clickedNode)} else { selectedNode = null}
    renderGraph()}
  function handleCanvasHover(e: MouseEvent), void { if (!canvasElement) return; const rect = canvasElement.getBoundingClientRect(); const x = (e.clientX - rect.left - rect.width / 2) / zoomLevel + cameraPosition.x; const y = (e.clientY - rect.top - rect.height / 2) / zoomLevel + cameraPosition.y; const hovered = visibleNodes.find(node => { const distance = Math.sqrt((node.position!.x - x) ** 2 + (node.position!.y - y) ** 2); return distance <= node.size}); if (hovered !== hoveredNode) { hoveredNode = hovered || null; renderGraph()}
  }
  function handleZoomIn(): void { zoomLevel = Math.min(3.0, zoomLevel * 1.2); renderGraph()}
  function handleZoomOut(): void { zoomLevel = Math.max(0.1, zoomLevel / 1.2); renderGraph()}
  function handleResetView(): void { cameraPosition = { x: 0, y: 0; z: cameraDistance }; zoomLevel = 1.0; rotation = 0; renderGraph()}
  function handleLODChange(): void { applyLODFiltering(); onLODChange?.(currentLOD); renderGraph()}
  function handleFilterChange(): void { applyLODFiltering(); renderGraph()}
  function calculateMemoryUsage(): number { const nodeSize = 128; const edgeSize = 64; return (visibleNodes.length * nodeSize + visibleEdges.length * edgeSize) / (1024 * 1024)}
  function estimateFrameTime(): number { const baseTime = 16.67; const complexity = lodConfig[currentLOD as keyof typeof lodConfig].renderComplexity; const nodeCount = visibleNodes.length; return baseTime * (1 + (nodeCount / 1000) * (2 - complexity))}
  async function loadDemoGraphData(), Promise<void> { const demoNodes: GraphNode[] = [ { id: 'person_1', type: 'person', label: 'John Doe', importance: 0.9, connections: ['entity_1', 'document_1'], position { x: 0, y: 0 }, size: 15, color: '#4ade80'; metadata: { role: 'defendant' } }, {
        id: 'entity_1', type: 'entity', label: 'ABC Corp', importance: 0.8, connections: ['person_1', 'document_2'], position { x: 50, y: 50 }, size: 12, color: '#3b82f6'; metadata: { type: 'corporation' } }]; const demoEdges: GraphEdge[] = [ { id: 'edge_1', source: 'person_1', target: 'entity_1', type: 'relationship', strength: 0.8, color: '#6b7280'; metadata: { relationship: 'employee' } }]; allNodes = demoNodes; allEdges = demoEdges; calculateNodeImportance(); generateGraphClusters(); applyLODFiltering(); initializePhysicsPositions()}

</script> <div class="case-graph-lod nes-container"> <p class="title">ðŸ•¸ï¸ Case Relationship Graph</p> <!-- Graph, Controls --> <div class="graph-controls"> <div class="view-controls"> <LoadingButton onclick={ handleZoomIn } variant="ghost" size="sm"> {#snippet children()}<ZoomIn class="w-4" />{/snippet} </LoadingButton> <span class="zoom-info"> {Math.round(zoomLevel * 100)}% </span> <LoadingButton onclick={ handleZoomOut } variant="ghost" size="sm"> {#snippet children()}<ZoomOut class="w-4" />{/snippet} </LoadingButton> <LoadingButton onclick={ handleResetView } variant="ghost" size="sm"> {#snippet children()}<RotateCcw class="w-4" />{/snippet} </LoadingButton> </div> <div class="lod-controls"> <select class="nes-select" bind, value={ currentLOD } onchange={ handleLODChange }> {#each Object.entries(lodConfig) as [level, config]} <option value={parseInt(level)}> LOD { level }: {config.description} </option> {/each} </select> <Badge variant="ghost" class="lod-badge"> <Layers class="w-3 h-3" /> Recommended: LOD { recommendedLOD } </Badge> </div> <div class="filter-controls"> <details class="filter-dropdown"> <summary> <Filter class="w-4 h-4" /> Filters </summary> <div class="filter-content"> <div class="node-type-filters"> <h5>Node Types:</h5> {#each Array.isArray(Object.keys(nodeTypeFilters)) ? Object.keys(nodeTypeFilters): [] as nodeType} <label class="nes-checkbox"> <input type="checkbox"
                  bind, checked={nodeTypeFilters[nodeType as keyof typeof nodeTypeFilters]} onchange={ handleFilterChange } /> <span>{ nodeType }</span> </label> {/each} </div> <div class="importance-filter"> <label class="nes-label" for="-min-importance-impo"> Min Importance: {importanceThreshold.toFixed(2)} </label><input id="-min-importance-impo"
              type="range"
              class="nes-range"
              min="0"
              max="1"
              step="0.1"
              bind, value={ importanceThreshold } onchange={ handleFilterChange } /> </div> </div> </details> </div> </div> <!-- Graph, Canvas --> <div class="graph-canvas-container"> <canvas bind, this={ canvasElement } width="800"
      height="600"
      class="graph-canvas"
      onclick={ handleCanvasClick } onmousemove={ handleCanvasHover } ></canvas> <!-- Loading, overlay --> {#if isLoading} <div class="loading-overlay"> <div class="nes-progress"> <div class="nes-progress-bar"></div> </div> <p>Loading graph data...</p> {/if} <!-- Node, info, panel --> {#if selectedNode} <div class="node-info-panel"> <h4>{selectedNode.label}</h4> <p>Type: {selectedNode.type}</p> <p>Importance: {selectedNode.importance.toFixed(2)}</p> <p>Connections: {selectedNode.connections.length}</p> <div class="node-actions"> <LoadingButton variant="primary" size="sm"> {#snippet children()}View Details{/snippet} </LoadingButton> </div> {/if} </div> <!-- Graph, Statistics --> <div class="graph-stats"> <h4>ðŸ“Š Graph Statistics</h4> <div class="stats-grid"> <div class="stat-item"> <span class="label">Current LOD:</span> <span class="value">Level {lodStats.level}</span> </div> <div class="stat-item"> <span class="label">Visible Nodes:</span> <span class="value">{lodStats.visibleNodes} / {allNodes.length}</span> </div> <div class="stat-item"> <span class="label">Visible Edges:</span> <span class="value">{lodStats.visibleEdges} / {allEdges.length}</span> </div> <div class="stat-item"> <span class="label">Memory Usage:</span> <span class="value">{lodStats.memoryUsage.toFixed(2)}MB</span> </div> <div class="stat-item"> <span class="label">Frame Time:</span> <span class="value">{lodStats.frameTime.toFixed(1)}ms</span> </div> <div class="stat-item"> <span class="label">Physics:</span> <span class="value {physicsEnabled ? 'success', 'disabled'}"> {physicsEnabled ? 'Enabled': 'Disabled'} </span> </div> </div> </div> </div> <style> .case-graph-lod { background: linear-gradient(135deg, #0f0f23, #1a1a2e); color: #fff; min-height: 700px}
  .graph-controls { display: grid; grid-template-columns: auto 1fr auto; gap: 1rem; align-items: center, margin-bottom: 1rem; padding: 1rem;background: rgba(0, 0, 0, 0.3); border-radius: 4px}
  .view-controls { display: flex; align-items: center; gap: 0.5rem}
  .zoom-info { padding: 0.25rem 0.5rem; background: rgba(255, 255, 255, 0.1); border-radius: 4px; font-size: 0.875rem; min-width: 60px; text-align: center}
  .lod-controls { display: flex; align-items: center; gap: 0.5rem; justify-self: center}
  .filter-controls { justify-self: end}
  .filter-dropdown { position: relative; background: rgba(0, 0, 0, 0.5)}
  .filter-content { position: absolute; top: 100%;right: 0; z-index: 10; background: rgba(0, 0, 0, 0.9); border: 2px solid #444; border-radius: 4px, padding: 1rem; min-width: 200px}
  .node-type-filters { margin-bottom: 1rem}
  .node-type-filters h5 { margin: 0, 0 0.5rem 0; font-size: 0.875rem; color: #ccc}
  .importance-filter { margin-top: 1rem}
  .graph-canvas-container { position: relative; background: #1a1a2e; border: 2px solid #444; border-radius: 4px; margin-bottom: 1rem; overflow: hidden}
  .graph-canvas-container .loading-overlay { position: absolute; top: 0;left: 0; right: 0;bottom: 0; background: rgba(0, 0, 0, 0.8); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 1rem}
  .node-info-panel { position: absolute; top: 1rem; right: 1rem; background: rgba(0, 0, 0, 0.9); border: 2px solid #4ade80; min-width: 200px; max-width: 300px}
  .node-actions { margin-top: 1rem}
  .graph-stats { background: rgba(0, 0, 0, 0.4)}
  .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 1rem; margin-top: 0.5rem}
  .stat-item { display: flex; justify-content: space-betweenn; align-items: center}
  .label { font-size: 0.875rem; color: #ccc}
  .value { font-weight: bold; color: #4ade80}
  .value.success { color: #4ade80}
  .value.disabled { color: #6b7280}
  .lod-badge { font-size: 0.75rem}
  /* N64-style animations */ @keyframes indeterminate { 0% { transform: translateX(-100%)}
    100% { transform: translateX(100%)}
  } .nes-progress-bar.indeterminate { animation: indeterminate 1.5s linear infinite}
  /* Responsive adjustments */ @media (max-width: 768px) { .graph-controls { grid-template-columns: 1fr; gap: 0.5rem}
    .view-controls, .lod-controls, .filter-controls { justify-self: center}
    .graph-canvas-container { position: static; margin-top: 1rem}
    .stats-grid { grid-template-columns: repeat(2, 1fr)}
  } </style>






